{"file_path":"/app/pystan_analysis.py","content":""""
Converted from /app/gp_rstan.R to Python using PyStan 3.10.0.

Loads the same data files, defines the functionally equivalent Stan model,
uses functionally equivalent posterior-sampling hyperparameters and computes
posterior means of alpha, sigma, rho, beta.
"""

import json
import os

import numpy as np
import stan

# ---------------------------------------------------------------------------
# Stan model code (functionally identical to the original R script's Stan model)
# ---------------------------------------------------------------------------
stan_code = """
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X); // == cols(X_new)
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

transformed parameters {
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                   + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);
}

model {
  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd   = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
"""


def main():
    base_dir = "/app"

    # --- Load data (same files as the R script) ---------------------------
    with open(os.path.join(base_dir, "meta_public.json")) as f:
        meta_pub = json.load(f)

    train_X = np.genfromtxt(
        os.path.join(base_dir, "train_X.csv"), delimiter=",", skip_header=1
    )
    test_X = np.genfromtxt(
        os.path.join(base_dir, "test_X.csv"), delimiter=",", skip_header=1
    )
    train_y = np.genfromtxt(
        os.path.join(base_dir, "train_y.csv"), delimiter=",", skip_header=1
    )

    P = int(meta_pub["P"])
    jitter = float(meta_pub["jitter"])

    N, D = train_X.shape
    N_new = test_X.shape[0]

    # H <- cbind(1, train_X[,1], train_X[,2]);  H_new <- cbind(1, test_X[,1], test_X[,2])
    H = np.column_stack([np.ones(N), train_X[:, 0], train_X[:, 1]])
    H_new = np.column_stack([np.ones(N_new), test_X[:, 0], test_X[:, 1]])

    data_list = {
        "N": N,
        "D": D,
        "X": train_X.tolist(),
        "P": P,
        "H": H.tolist(),
        "y": train_y.tolist(),
        "jitter": jitter,
        "N_new": N_new,
        "X_new": test_X.tolist() if N_new > 0 else [],
        "H_new": H_new.tolist() if N_new > 0 else [],
    }

    # --- Build model (random_seed must be 1) ------------------------------
    posterior = stan.build(program_code=stan_code, data=data_list, random_seed=1)

    # --- Posterior sampling (equivalent to RStan sampling call) -----------
    # R: chains=4, iter=2000, warmup=1000, thin=2  <=>  num_warmup=1000,
    #    num_samples=1000, num_thin=2, num_chains=4
    # R: seed=1  <=>  random_seed=1 in stan.build
    # R: init_r=0.1  <=>  init_radius=0.1
    # R control list: adapt_delta=0.93, max_treedepth=14, adapt_gamma=0.05,
    # adapt_kappa=0.75, adapt_t0=10, adapt_init_buffer=100,
    # adapt_term_buffer=50, adapt_window=25
    fit = posterior.sample(
